#pragma once
// SYSTEM > NETWORK > HOW TO PLAY ONLINE (0.17.7): an index of sections and
// their pages, generated by host/make_play_help.py. A page: row 0 the title,
// 1-5 the text, 6 the footer; a leading '!' means white.
enum { kPlayHelpRows = 7 };
typedef struct {
    const char *Name;   // the index row
    int First, Pages;   // into g_PlayHelp
} PlayHelpSection_t;
extern const char *const g_PlayHelp[][kPlayHelpRows];
extern const int g_PlayHelpPages;
extern const PlayHelpSection_t g_PlayHelpSections[];
extern const int g_PlayHelpNumSections;
